<h3 class="h4">Registr aktuálních položek</h3><p>Oprava používá stejný klíč; starší verze zůstává zachována. Textové doložení je záznam obsluhy, nikoli automatické ověření externí služby.</p><table class="table"><thead><tr><th>Klíč / druh</th><th>Obsah</th><th>Odpovědnost</th><th>Důkaz</th></tr></thead><tbody><?php foreach($entries as$key=>$e):?><tr><td><?=cutoverH($key.' / '.$forms[$e['kind']][0])?></td><td><?=cutoverH($e['data']['title'])?></td><td>#<?=(int)$e['data']['owner_trainer_id']?></td><td><?=cutoverH($e['data']['evidence'])?></td></tr><?php endforeach;?></tbody></table>
<?php foreach($forms as$kind=>[$title,$fields]):?><details class="mb-3"><summary>Zapsat / opravit: <?=$title?></summary><form method="post" class="card card-body"><?=csrf_field()?><input type="hidden" name="action" value="entry"><input type="hidden" name="run_id" value="<?=$id?>"><input type="hidden" name="revision" value="<?=(int)$run['revision']?>"><input type="hidden" name="kind" value="<?=$kind?>"><label>Jedinečný klíč položky<input class="form-control" name="entry_key" pattern="[a-z0-9._:-]+" required maxlength="100"></label><label>Název<input class="form-control" name="title" required maxlength="160"></label><label>Odpovědná osoba<select class="form-select" name="owner_trainer_id" required><?php foreach($owners as$o):?><option value="<?=(int)$o['id']?>"><?=cutoverH($o['jmeno'])?></option><?php endforeach;?></select></label><?php foreach($fields as$key=>$definition):if(is_array($definition)):?><label><?=$definition[0]?><select class="form-select" name="<?=$key?>"><?php foreach($definition[1]as$value=>$label):?><option value="<?=$value?>"><?=$label?></option><?php endforeach;?></select></label><?php else:?><label><?=$definition?><input class="form-control" name="<?=$key?>" required maxlength="2000"></label><?php endif;endforeach;?><label>Konkrétní důkaz a jeho umístění<textarea class="form-control" name="evidence" required maxlength="2000"></textarea></label><label>Důvod zápisu<input class="form-control" name="reason" required maxlength="1000"></label><label class="my-2"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji zápis podkladu přípravy.</label><button class="btn btn-primary">Uložit novou verzi položky</button></form></details><?php endforeach;?>
